"""Virtual address space auditing for the wvas diagnostic collector.

The collector asks three questions about a target process:

``regions(pid)``
    Which parts of the virtual address space does the process have in use?

``file_backed_regions(pid)``
    Which of those parts are backed by a file on disk, and which file?

``modules(pid)``
    Which executable images are loaded, and where?

The answers are what the field engineers read when a machine reports
"something keeps the log file mapped" or "the process has no address space
left". They are compared against what a debugger shows and pasted into
support tickets, so every number has to be the one the system reports, at
full address width, and every path has to be one the caller can open.
"""

import ctypes
import os

from . import _winapi as w
from .errors import WVasError

# Characters in the scratch buffers used for names. GetMappedFileNameW wants
# its buffer size in characters, GetFinalPathNameByHandleW in characters too;
# 1 KiB characters comfortably covers \\?\Volume{...} style paths and long
# UNC names.
NAME_BUFFER_CHARS = 1024

# Device name prefixes the kernel hands back for a mapped file. None of them
# is a path a caller can open, so every one of them has to be translated.
_NT_PREFIXES = ("\\Device\\", "\\??\\", "\\\\")

_PROTECTION_NAMES = {
    w.PAGE_NOACCESS: "none",
    w.PAGE_READONLY: "r",
    w.PAGE_READWRITE: "rw",
    w.PAGE_WRITECOPY: "wc",
    w.PAGE_EXECUTE: "x",
    w.PAGE_EXECUTE_READ: "xr",
    w.PAGE_EXECUTE_READWRITE: "xrw",
    w.PAGE_EXECUTE_WRITECOPY: "xwc",
}

_TYPE_NAMES = {
    w.MEM_IMAGE: "image",
    w.MEM_MAPPED: "mapped",
    w.MEM_PRIVATE: "private",
}

# A file identity: volume serial number plus file index. Two paths that share
# it are the same file, which is how modules() tells that the same image
# mapped twice is still one module.
def _file_id(path):
    try:
        stat = os.stat(path)
    except OSError:
        return None
    return (getattr(stat, "st_dev", None), getattr(stat, "st_ino", None))


def protection_name(protect):
    """Map a PAGE_* protection value onto its short textual name.

    Pure lookup: the modifier flags a region may carry (PAGE_GUARD,
    PAGE_NOCACHE, PAGE_WRITECOMBINE) are stripped, no process is queried.
    """
    return _PROTECTION_NAMES.get(protect & 0xFF, "?")


def type_name(region_type):
    """Map a MEM_* region type onto its short textual name.

    Pure lookup, no process is queried.
    """
    return _TYPE_NAMES.get(region_type, "private")


# ---------------------------------------------------------------------------
# error classification
# ---------------------------------------------------------------------------

def _ensure_supported():
    if not w.is_windows():
        raise WVasError(
            "wvas audits Windows address spaces only", kind="unsupported"
        )


def _check_pid(pid):
    if isinstance(pid, bool) or not isinstance(pid, int) or pid < 0:
        raise WVasError(
            "pid must be a non-negative integer, got %r" % (pid,),
            kind="badarg",
            pid=pid,
        )


def _process_exists(pid):
    """True when ``pid`` names a process that is running right now."""
    try:
        handle = w.OpenProcess(w.PROCESS_QUERY_LIMITED_INFORMATION, False, pid)
    except (AttributeError, OSError):
        handle = None
    if handle:
        w.CloseHandle(handle)
        return True
    if w.last_error() != w.ERROR_ACCESS_DENIED:
        return False
    # Access denied is only ever reported for a process that exists.
    snapshot = ctypes.create_string_buffer(4 * 4096)
    needed = w.DWORD(0)
    if not w.EnumProcesses(ctypes.cast(snapshot, w.PDWORD), 4 * 4096, ctypes.byref(needed)):
        return False
    found = ctypes.cast(snapshot, ctypes.POINTER(w.DWORD))
    return any(found[i] == pid for i in range(needed.value // 4))


def _classify_open_failure(error, pid):
    """Pick the error kind for a failed OpenProcess."""
    if error == w.ERROR_ACCESS_DENIED:
        kind = "access-denied"
    elif error == w.ERROR_INVALID_PARAMETER or not _process_exists(pid):
        kind = "no-such-process"
    else:
        kind = "query-failed"
    raise WVasError(
        "cannot open process %s (Win32 error %s)" % (pid, error), kind=kind, pid=pid
    )


def _open_process(pid):
    """Open ``pid`` for address space inspection."""
    _ensure_supported()
    _check_pid(pid)
    desired = (
        w.PROCESS_QUERY_INFORMATION
        | w.PROCESS_QUERY_LIMITED_INFORMATION
        | w.PROCESS_VM_READ
    )
    handle = w.OpenProcess(desired, False, pid)
    if not handle:
        error = w.last_error()
        if error == w.ERROR_ACCESS_DENIED:
            # Reading mapped file names needs the full query right; the
            # limited one is enough to walk the address space itself.
            handle = w.OpenProcess(w.PROCESS_QUERY_LIMITED_INFORMATION, False, pid)
    if not handle:
        _classify_open_failure(w.last_error(), pid)
    return handle


def _close_process(handle):
    if handle:
        w.CloseHandle(handle)


# ---------------------------------------------------------------------------
# path translation
# ---------------------------------------------------------------------------

def _dos_devices(drive):
    """The NT device names a drive letter stands for, longest first."""
    buffer = ctypes.create_unicode_buffer(NAME_BUFFER_CHARS)
    written = w.QueryDosDeviceW(drive, buffer, NAME_BUFFER_CHARS)
    if not written:
        return ()
    names = tuple(part for part in buffer.value.split("\0") if part)
    return tuple(sorted(names, key=len, reverse=True))


class _DeviceMap(object):
    """Lazily built map of NT device names -> openable DOS/UNC prefixes."""

    def __init__(self):
        self._map = None

    def _drives(self):
        buffer = ctypes.create_unicode_buffer(512)
        length = w.GetLogicalDriveStringsW(512, buffer)
        if not length:
            return ()
        return tuple(part for part in buffer.value.split("\0") if part)

    def build(self):
        entries = {}
        for drive in self._drives():
            letter = drive.rstrip("\\")
            for device in _dos_devices(letter):
                entries.setdefault(device, letter)
        # A network drive reports \\server\share as its device name; keep it
        # reachable under the \\?\ form CreateFile accepts as well.
        for device, prefix in list(entries.items()):
            if device.startswith("\\\\"):
                entries.setdefault("\\??\\UNC" + device[1:], prefix)
        return entries

    def lookup(self, device):
        if self._map is None:
            self._map = self.build()
        return self._map.get(device)


_DEVICE_MAP = _DeviceMap()


def _is_openable(path):
    """True for a path a caller can hand to ``open()`` or Explorer."""
    if not path:
        return False
    if path.startswith("\\Device\\") or path.startswith("\\??\\"):
        return False
    if path.startswith("\\"):
        # A bare \server\share style path is not openable as written; the
        # UNC form with the leading backslash pair is.
        return path.startswith("\\\\") and not path.startswith("\\\\.\\")
    return len(path) > 2 and path[1] == ":"


def _strip_volume_prefix(path):
    """Drop the \\?\ / \\.\ volume prefixes CreateFile accepts."""
    if path.startswith("\\\\?\\UNC\\"):
        return "\\\\" + path[8:]
    if path.startswith("\\\\?\\") or path.startswith("\\\\.\\"):
        return path[4:]
    return path


def _translate_device_path(device_path):
    """Turn ``\\Device\\Volume\\dir\\file`` into a path the caller can open.

    Returns ``None`` when the name cannot be mapped back onto a DOS drive or
    a UNC share: a name nobody can open is not a useful answer for a ticket,
    so it is reported as "no usable file name".
    """
    if not device_path:
        return None
    if _is_openable(device_path):
        return _strip_volume_prefix(device_path)
    if device_path.startswith("\\??\\"):
        return _translate_device_path(device_path[4:])

    index = device_path.find("\\", 1)
    if index <= 0:
        return None
    device = device_path[:index]
    rest = device_path[index:]

    if device.lower() in ("\\device\\mup", "\\device\\lanmanredirector", "\\device\\webdavredirector"):
        candidate = "\\\\" + rest.lstrip("\\")
        return candidate if _is_openable(candidate) else None

    if device.startswith("\\device\\unc"):
        candidate = "\\\\" + rest.lstrip("\\")
        return candidate if _is_openable(candidate) else None

    prefix = _DEVICE_MAP.lookup(device)
    if prefix is None:
        prefix = _DEVICE_MAP.lookup(device.lower())
    if prefix is None:
        return None
    return prefix + rest


def _open_for_metadata(path):
    """Open ``path`` read-metadata-only, or return ``None``."""
    handle = w.CreateFileW(
        path,
        0,
        w.FILE_SHARE_READ | w.FILE_SHARE_WRITE | w.FILE_SHARE_DELETE,
        None,
        w.OPEN_EXISTING,
        w.FILE_FLAG_BACKUP_SEMANTICS,
        None,
    )
    if not handle or handle == w.INVALID_HANDLE_VALUE:
        return None
    return handle


def _final_dos_path(device_path):
    """Resolve an NT device name to a DOS path through the object manager.

    ``\\\\.\\GLOBALROOT\\<device path>`` lets the object manager do the walk,
    and ``GetFinalPathNameByHandle`` reports the result the way the file
    system knows it, including for volumes that have no drive letter.
    """
    handle = _open_for_metadata("\\\\.\\GLOBALROOT" + device_path)
    if handle is None:
        return None
    try:
        buffer = ctypes.create_unicode_buffer(NAME_BUFFER_CHARS)
        written = w.GetFinalPathNameByHandleW(
            handle, buffer, NAME_BUFFER_CHARS, w.VOLUME_NAME_DOS
        )
        if not written:
            return None
        if written >= NAME_BUFFER_CHARS:  # pragma: no cover - absurdly long
            bigger = ctypes.create_unicode_buffer(written + 1)
            if not w.GetFinalPathNameByHandleW(bigger and handle, bigger, written + 1, w.VOLUME_NAME_DOS):
                return None
            buffer = bigger
        path = _strip_volume_prefix(buffer.value)
        return path if _is_openable(path) else None
    finally:
        w.CloseHandle(handle)


def _usable_file_path(device_path):
    """The openable path behind an NT device name, or ``None``."""
    if not device_path:
        return None
    if _is_openable(device_path):
        return _strip_volume_prefix(device_path)
    path = _translate_device_path(device_path)
    if path is not None:
        return path
    return _final_dos_path(device_path)


def _mapped_device_name(handle, address):
    """The raw NT device name PSAPI reports for the file at ``address``."""
    buffer = ctypes.create_unicode_buffer(NAME_BUFFER_CHARS)
    written = w.GetMappedFileNameW(
        handle, ctypes.c_void_p(address), buffer, NAME_BUFFER_CHARS
    )
    if not written:
        # No name at all: anonymous mapping, decommitted view, a file that
        # vanished. Callers read that as "nothing backs this region".
        return None
    if written >= NAME_BUFFER_CHARS:  # pragma: no cover - absurdly long
        bigger = ctypes.create_unicode_buffer(written + 1)
        if not w.GetMappedFileNameW(handle, ctypes.c_void_p(address), bigger, written + 1):
            return None
        return bigger.value
    return buffer.value


# ---------------------------------------------------------------------------
# region walk
# ---------------------------------------------------------------------------

def _query_region(handle, address, mbi):
    """One VirtualQueryEx step; returns the region size or ``None``.

    ``None`` means the address is past the end of the process' address space
    or the target went away mid-walk, neither of which is a failed query.
    """
    written = w.VirtualQueryEx(
        handle, ctypes.c_void_p(address), ctypes.byref(mbi), ctypes.sizeof(mbi)
    )
    if written:
        return written
    if w.last_error() in w.END_OF_SPACE_ERRORS:
        return None
    raise WVasError(
        "VirtualQueryEx failed (Win32 error %s)" % w.last_error(), kind="query-failed"
    )


def _walk_regions(handle):
    """Yield ``(mbi, struct type)`` for every region of the target, in order."""
    struct = w.mbi_struct(handle)
    if struct is w.MEMORY_BASIC_INFORMATION64:
        limit = (1 << 47) - 1
    else:
        # A 32-bit target still has its image and system areas reported above
        # the 2 GiB line; walk the whole 4 GiB user space.
        limit = (1 << 32) - 1
    mbi = struct()
    address = 0
    while address <= limit:
        if _query_region(handle, address, mbi) is None:
            return
        base = int(mbi.BaseAddress or 0)
        size = int(mbi.RegionSize or 0)
        if mbi.State in (w.MEM_COMMIT, w.MEM_RESERVE):
            yield mbi, struct
        if size == 0:
            return
        next_address = base + size
        if next_address <= address:
            return
        address = next_address


def _describe(handle, mbi):
    """Build one region descriptor from a filled-in MEMORY_BASIC_INFORMATION."""
    base = int(mbi.BaseAddress or 0) & w.ADDRESS_MASK
    size = int(mbi.RegionSize or 0) & w.ADDRESS_MASK
    region_type = int(mbi.Type or 0)
    state = int(mbi.State or 0)
    protect = int(mbi.Protect or 0)
    if protect == 0:
        # Reserved memory carries no protection of its own; report the one the
        # whole allocation was reserved with.
        protect = int(getattr(mbi, "AllocationProtect", 0) or 0)

    path = None
    if state == w.MEM_COMMIT and region_type in (w.MEM_IMAGE, w.MEM_MAPPED):
        name = _mapped_device_name(handle, base)
        if name:
            path = _usable_file_path(name)

    return {
        "base": base,
        "size": size,
        "state": "commit" if state == w.MEM_COMMIT else "reserve",
        "type": type_name(region_type),
        "protect": protection_name(protect),
        "path": path,
        "image": region_type == w.MEM_IMAGE,
    }


def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    Every committed region is reported, and every reserved one too unless
    ``include_reserved`` is false. Addresses and sizes come back at full
    width, ascending by ``base``.
    """
    handle = _open_process(pid)
    try:
        result = []
        for mbi, _struct in _walk_regions(handle):
            if not include_reserved and mbi.State != w.MEM_COMMIT:
                continue
            result.append(_describe(handle, mbi))
        result.sort(key=lambda item: (item["base"], item["size"]))
        return result
    finally:
        _close_process(handle)


def file_backed_regions(pid):
    """Return only the regions that have a file behind them."""
    return [item for item in regions(pid) if item["path"] is not None]


# ---------------------------------------------------------------------------
# module list
# ---------------------------------------------------------------------------

def _module_path(handle, module):
    """The openable path of a loaded module, or ``None`` when it has none."""
    buffer = ctypes.create_unicode_buffer(NAME_BUFFER_CHARS)
    written = w.GetModuleFileNameExW(handle, module, buffer, NAME_BUFFER_CHARS)
    name = buffer.value if written else ""
    if not name:
        # Last resort: ask the address space what is mapped at this base.
        info = w.MODULEINFO()
        if w.GetModuleInformation(handle, module, ctypes.byref(info), ctypes.sizeof(info)):
            name = _mapped_device_name(handle, info.lpBaseOfDll or 0) or ""
    return _usable_file_path(name)


def _module_record(handle, module, cache):
    """One module entry, or ``None`` when it cannot be described."""
    info = w.MODULEINFO()
    if not w.GetModuleInformation(
        handle, module, ctypes.byref(info), ctypes.sizeof(info)
    ):
        return None
    base = int(info.lpBaseOfDll or 0) & w.ADDRESS_MASK
    if not base:
        return None
    path = _module_path(handle, module)
    if path is not None and path in cache:
        # The same image file shows up once per mapping; the manifest keeps
        # one entry per file.
        return None
    if path is not None:
        cache.add(path)
    return {"path": path, "base": base, "size": int(info.SizeOfImage or 0)}


def modules(pid):
    """Return the loaded executable images, lowest base address first.

    Each image is listed once and each file path appears once, so an image
    mapped at several addresses does not fill the manifest with duplicates.
    An image whose path cannot be resolved is still listed, with ``None``.
    """
    handle = _open_process(pid)
    try:
        entries = []
        seen_bases = set()
        seen_paths = set()
        for filter_flag in (
            w.LIST_MODULES_DEFAULT,
            w.LIST_MODULES_32BIT,
            w.LIST_MODULES_64BIT,
        ):
            slot_count = 1024
            for _attempt in range(4):
                buffer = (w.HMODULE * slot_count)()
                needed = w.DWORD(0)
                if not w.EnumProcessModulesEx(
                    handle, buffer, ctypes.sizeof(buffer), ctypes.byref(needed), filter_flag
                ):
                    break
                count = min(needed.value // ctypes.sizeof(w.HMODULE), slot_count)
                for index in range(count):
                    module = buffer[index]
                    if not module:
                        continue
                    key = int(module or 0) & w.ADDRESS_MASK
                    if key in seen_bases:
                        continue
                    seen_bases.add(key)
                    record = _module_record(handle, module, seen_paths)
                    if record is not None:
                        entries.append(record)
                if needed.value <= ctypes.sizeof(buffer):
                    break
                slot_count *= 2
        entries.sort(key=lambda item: item["base"])
        return entries
    finally:
        _close_process(handle)

"""Virtual address space auditing for the wvas diagnostic collector.

The collector asks three questions about a target process:

``regions(pid)``
    Which parts of the virtual address space does the process have in use?

``file_backed_regions(pid)``
    Which of those parts are backed by a file on disk, and which file?

``modules(pid)``
    Which executable images are loaded, and where?

The answers are what the field engineers read when a machine reports
"something keeps the log file mapped" or "the process has no address space
left". They are held next to what a debugger shows and pasted into support
tickets, so every address has to be the one the system reports, at full
address width, and every path has to be one the caller can actually open.
"""

import ctypes

from . import _winapi as w
from .errors import WVasError

# Characters in the scratch buffers used for names. 1 KiB comfortably covers
# \\?\Volume{...} style paths, long UNC names and the redirected device names
# a host shares into a virtual machine.
NAME_BUFFER_CHARS = 1024

# Prefixes the object manager uses. None of them names something a caller can
# open, so every one of them has to be translated before it is reported.
_UNC_LIKE_DEVICES = (
    "\\device\\mup",
    "\\device\\lanmanredirector",
    "\\device\\webdavredirector",
    "\\device\\davwwwroot",
    "\\device\\tsclient",
)

_PROTECTION_NAMES = {
    w.PAGE_NOACCESS: "none",
    w.PAGE_READONLY: "r",
    w.PAGE_READWRITE: "rw",
    w.PAGE_WRITECOPY: "wc",
    w.PAGE_EXECUTE: "x",
    w.PAGE_EXECUTE_READ: "xr",
    w.PAGE_EXECUTE_READWRITE: "xrw",
    w.PAGE_EXECUTE_WRITECOPY: "xwc",
}

_TYPE_NAMES = {
    w.MEM_IMAGE: "image",
    w.MEM_MAPPED: "mapped",
    w.MEM_PRIVATE: "private",
}


def protection_name(protect):
    """Map a PAGE_* protection value onto its short textual name.

    A pure lookup: the modifier flags a region may carry (PAGE_GUARD,
    PAGE_NOCACHE, PAGE_WRITECOMBINE) are stripped, no process is queried.
    """
    return _PROTECTION_NAMES.get(protect & 0xFF, "?")


def type_name(region_type):
    """Map a MEM_* region type onto its short textual name.

    A pure lookup, no process is queried.
    """
    return _TYPE_NAMES.get(region_type, "private")


# ---------------------------------------------------------------------------
# opening the target
# ---------------------------------------------------------------------------

def _ensure_supported():
    if not w.is_windows():
        raise WVasError("wvas audits Windows address spaces only", kind="unsupported")


def _check_pid(pid):
    if isinstance(pid, bool) or not isinstance(pid, int) or pid < 0:
        raise WVasError(
            "pid must be a non-negative integer, got %r" % (pid,),
            kind="badarg",
            pid=pid,
        )


def _process_exists(pid):
    """True when ``pid`` names a process that is running right now."""
    handle = w.OpenProcess(w.PROCESS_QUERY_LIMITED_INFORMATION, False, pid)
    if handle:
        w.CloseHandle(handle)
        return True
    if w.last_error() != w.ERROR_ACCESS_DENIED:
        return False
    # Access denied is only reported for a process that does exist.
    snapshot = ctypes.create_string_buffer(4 * 4096)
    needed = w.DWORD(0)
    if not w.EnumProcesses(
        ctypes.cast(snapshot, w.PDWORD), ctypes.sizeof(snapshot), ctypes.byref(needed)
    ):
        return False
    found = ctypes.cast(snapshot, ctypes.POINTER(w.DWORD))
    return any(found[i] == pid for i in range(needed.value // 4))


def _fail_to_open(error, pid):
    """Raise the classified failure for an OpenProcess that did not work."""
    if error == w.ERROR_ACCESS_DENIED:
        kind = "access-denied"
    elif error == w.ERROR_INVALID_PARAMETER or not _process_exists(pid):
        kind = "no-such-process"
    else:
        kind = "query-failed"
    raise WVasError(
        "cannot open process %s (Win32 error %s)" % (pid, error), kind=kind, pid=pid
    )


def _open_process(pid):
    """Open ``pid`` so its address space can be inspected."""
    _ensure_supported()
    _check_pid(pid)
    handle = w.OpenProcess(
        w.PROCESS_QUERY_INFORMATION
        | w.PROCESS_QUERY_LIMITED_INFORMATION
        | w.PROCESS_VM_READ,
        False,
        pid,
    )
    if not handle and w.last_error() == w.ERROR_ACCESS_DENIED:
        # Reading mapped file names wants the full query right, but walking
        # the address space itself only needs the limited one.
        handle = w.OpenProcess(w.PROCESS_QUERY_LIMITED_INFORMATION, False, pid)
    if not handle:
        _fail_to_open(w.last_error(), pid)
    return handle


def _close_process(handle):
    if handle:
        w.CloseHandle(handle)


# ---------------------------------------------------------------------------
# turning a device name into a path the caller can open
# ---------------------------------------------------------------------------

def _is_openable(path):
    """True for a path the caller can hand to ``open()`` or to Explorer."""
    if not path:
        return False
    if path.startswith("\\\\"):
        # \\server\share is a UNC path; \\?\ and \\.\ are object manager
        # syntax that no shell understands.
        return not path.startswith("\\\\?\\") and not path.startswith("\\\\.\\")
    if path.startswith("\\"):
        return False
    return len(path) > 2 and path[1] == ":"


def _strip_volume_prefix(path):
    """Drop the volume prefixes CreateFile accepts but callers do not want."""
    if path.startswith("\\\\?\\UNC\\"):
        return "\\\\" + path[8:]
    if path.startswith("\\\\?\\") or path.startswith("\\\\.\\"):
        return path[4:]
    return path


def _dos_devices(drive):
    """The NT device names a drive letter stands for, longest first."""
    buffer = ctypes.create_unicode_buffer(NAME_BUFFER_CHARS)
    written = w.QueryDosDeviceW(drive, buffer, NAME_BUFFER_CHARS)
    if not written:
        return ()
    names = tuple(part for part in buffer.value.split("\0") if part)
    return tuple(sorted(names, key=len, reverse=True))


class _DeviceMap(object):
    """Lazily built map of NT device names onto openable DOS/UNC prefixes."""

    def __init__(self):
        self._map = None

    def _drives(self):
        buffer = ctypes.create_unicode_buffer(512)
        length = w.GetLogicalDriveStringsW(512, buffer)
        if not length:
            return ()
        return tuple(part for part in buffer.value.split("\0") if part)

    def _build(self):
        entries = {}
        for drive in self._drives():
            letter = drive.rstrip("\\")
            for device in _dos_devices(letter):
                entries.setdefault(device, letter)
        # A network drive reports \\server\share as its device name; keep it
        # reachable under the \??\UNC form the object manager uses too.
        for device, prefix in list(entries.items()):
            if device.startswith("\\\\"):
                entries.setdefault("\\??\\UNC" + device[1:], prefix)
        return entries

    def lookup(self, device):
        if self._map is None:
            try:
                self._map = self._build()
            except WVasError:  # pragma: no cover - defensive
                self._map = {}
        return self._map.get(device)


_DEVICE_MAP = _DeviceMap()


def _translate_device_path(device_path):
    """Turn ``\\Device\\Volume\\dir\\file`` into a path the caller can open.

    Returns ``None`` when the name cannot be mapped back onto a DOS drive or
    a UNC share: a name nobody can open is not an answer a support ticket can
    use, so it is reported as "no usable file name" instead.
    """
    if not device_path:
        return None
    if _is_openable(device_path):
        return _strip_volume_prefix(device_path)

    if device_path.startswith("\\??\\UNC\\"):
        return "\\\\" + device_path[8:]
    if device_path.startswith("\\??\\"):
        return _translate_device_path(device_path[4:])
    if device_path.startswith("\\\\.\\GLOBALROOT\\"):
        return _translate_device_path(device_path[16:])

    index = device_path.find("\\", 1)
    if index <= 0:
        return None
    device = device_path[:index]
    rest = device_path[index:]

    if device.lower() in _UNC_LIKE_DEVICES or device.lower().startswith("\\device\\unc"):
        candidate = "\\\\" + rest.lstrip("\\")
        return candidate if _is_openable(candidate) else None

    prefix = _DEVICE_MAP.lookup(device)
    if prefix is None:
        prefix = _DEVICE_MAP.lookup(device.lower())
    if prefix is None:
        return None
    return prefix + rest


def _open_for_metadata(path):
    """Open ``path`` for metadata only, or return ``None``."""
    handle = w.CreateFileW(
        path,
        0,
        w.FILE_SHARE_READ | w.FILE_SHARE_WRITE | w.FILE_SHARE_DELETE,
        None,
        w.OPEN_EXISTING,
        w.FILE_FLAG_BACKUP_SEMANTICS,
        None,
    )
    if not handle or handle == w.INVALID_HANDLE_VALUE:
        return None
    return handle


def _final_dos_path(device_path):
    """Resolve an NT device name to a DOS path through the object manager.

    ``\\\\.\\GLOBALROOT\\<device path>`` lets the object manager walk the name,
    and ``GetFinalPathNameByHandle`` reports where the file system has it,
    which also covers volumes that carry no drive letter.
    """
    handle = _open_for_metadata("\\\\.\\GLOBALROOT" + device_path)
    if handle is None:
        return None
    try:
        buffer = ctypes.create_unicode_buffer(NAME_BUFFER_CHARS)
        written = w.GetFinalPathNameByHandleW(
            handle, buffer, NAME_BUFFER_CHARS, w.VOLUME_NAME_DOS
        )
        if written >= NAME_BUFFER_CHARS:
            bigger = ctypes.create_unicode_buffer(written + 1)
            written = w.GetFinalPathNameByHandleW(
                handle, bigger, written + 1, w.VOLUME_NAME_DOS
            )
            if not written:
                return None
            buffer = bigger
        if not written:
            return None
        path = _strip_volume_prefix(buffer.value)
        return path if _is_openable(path) else None
    finally:
        w.CloseHandle(handle)


def _usable_file_path(name):
    """The openable path behind a name PSAPI reported, or ``None``."""
    if not name:
        return None
    path = _translate_device_path(name)
    if path is not None:
        return path
    if name.startswith("\\"):
        return _final_dos_path(name)
    return None


def _mapped_device_name(handle, address):
    """The raw name PSAPI reports for the file backing ``address``."""
    buffer = ctypes.create_unicode_buffer(NAME_BUFFER_CHARS)
    written = w.GetMappedFileNameW(
        handle, ctypes.c_void_p(address), buffer, NAME_BUFFER_CHARS
    )
    if not written:
        # Nothing is named here: an anonymous mapping, a decommitted view, or
        # a file that has since gone away. Callers read that as "no file".
        return None
    if written >= NAME_BUFFER_CHARS:
        bigger = ctypes.create_unicode_buffer(written + 1)
        if not w.GetMappedFileNameW(
            handle, ctypes.c_void_p(address), bigger, written + 1
        ):
            return None
        return bigger.value
    return buffer.value


# ---------------------------------------------------------------------------
# walking the address space
# ---------------------------------------------------------------------------

def _query_region(handle, address, mbi):
    """One VirtualQueryEx step.

    Returns the number of bytes written, or ``None`` when ``address`` lies
    past the end of the target's address space. Anything else is a query that
    genuinely failed and is reported as such.
    """
    written = w.VirtualQueryEx(
        handle, ctypes.c_void_p(address), ctypes.byref(mbi), ctypes.sizeof(mbi)
    )
    if written:
        return written
    if w.last_error() in w.END_OF_SPACE_ERRORS:
        return None
    raise WVasError(
        "VirtualQueryEx failed at 0x%x (Win32 error %s)" % (address, w.last_error()),
        kind="query-failed",
    )


def _walk_regions(handle):
    """Yield the MEMORY_BASIC_INFORMATION of every region, low to high.

    The structure is filled in at the width the *target* process reports
    with, so a 64-bit address and a region larger than 4 GiB both arrive
    intact no matter how wide this interpreter is.
    """
    struct = w.mbi_struct(handle)
    if struct is w.MEMORY_BASIC_INFORMATION64:
        limit = (1 << 47) - 1
    else:
        limit = (1 << 32) - 1
    mbi = struct()
    address = 0
    while address <= limit:
        if _query_region(handle, address, mbi) is None:
            return
        base = int(mbi.BaseAddress or 0)
        size = int(mbi.RegionSize or 0)
        if mbi.State in (w.MEM_COMMIT, w.MEM_RESERVE):
            yield mbi
        if size == 0:
            return
        next_address = base + size
        if next_address <= address:
            return
        address = next_address


def _describe(handle, mbi):
    """Build one region descriptor from a filled-in MEMORY_BASIC_INFORMATION."""
    base = int(mbi.BaseAddress or 0) & w.ADDRESS_MASK
    size = int(mbi.RegionSize or 0) & w.ADDRESS_MASK
    region_type = int(mbi.Type or 0)
    state = int(mbi.State or 0)
    protect = int(mbi.Protect or 0)
    if protect == 0:
        # Reserved memory carries no protection of its own; report the one the
        # allocation as a whole was reserved with.
        protect = int(mbi.AllocationProtect or 0)

    path = None
    if state == w.MEM_COMMIT and region_type in (w.MEM_IMAGE, w.MEM_MAPPED):
        name = _mapped_device_name(handle, base)
        if name:
            path = _usable_file_path(name)

    return {
        "base": base,
        "size": size,
        "state": "commit" if state == w.MEM_COMMIT else "reserve",
        "type": type_name(region_type),
        "protect": protection_name(protect),
        "path": path,
        "image": region_type == w.MEM_IMAGE,
    }


def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    Every committed region is reported, and every reserved one too unless
    ``include_reserved`` is false. Addresses and sizes come back at full
    width, and the list is ascending by ``base``.
    """
    handle = _open_process(pid)
    try:
        result = []
        for mbi in _walk_regions(handle):
            if not include_reserved and mbi.State != w.MEM_COMMIT:
                continue
            result.append(_describe(handle, mbi))
        result.sort(key=lambda item: (item["base"], item["size"]))
        return result
    finally:
        _close_process(handle)


def file_backed_regions(pid):
    """Return only the regions that have a file behind them."""
    return [item for item in regions(pid) if item["path"] is not None]


# ---------------------------------------------------------------------------
# the module manifest
# ---------------------------------------------------------------------------

def _module_path(handle, module, base):
    """The openable path of a loaded module, or ``None`` when it has none."""
    buffer = ctypes.create_unicode_buffer(NAME_BUFFER_CHARS)
    written = w.GetModuleFileNameExW(handle, module, buffer, NAME_BUFFER_CHARS)
    name = buffer.value if written else ""
    if not name:
        # Last resort: ask the address space what is mapped at this base.
        name = _mapped_device_name(handle, base) or ""
    return _usable_file_path(name)


def _module_record(handle, module, seen_paths):
    """One module entry, or ``None`` when it repeats a file already listed."""
    base = int(module or 0) & w.ADDRESS_MASK
    size = 0
    info = w.MODULEINFO()
    if w.GetModuleInformation(handle, module, ctypes.byref(info), ctypes.sizeof(info)):
        base = int(info.lpBaseOfDll or 0) & w.ADDRESS_MASK or base
        size = int(info.SizeOfImage or 0)
    if not base:
        return None
    path = _module_path(handle, module, base)
    if path is not None:
        if path in seen_paths:
            # The same image file turns up once per mapping; the manifest
            # keeps a single entry per file.
            return None
        seen_paths.add(path)
    return {"path": path, "base": base, "size": size}


def _enumerate_modules(handle):
    """Yield ``(base, record)`` for every module PSAPI can see."""
    seen_bases = set()
    for filter_flag in (
        w.LIST_MODULES_ALL,
        w.LIST_MODULES_DEFAULT,
        w.LIST_MODULES_32BIT,
        w.LIST_MODULES_64BIT,
    ):
        slot_count = 1024
        for _attempt in range(6):
            buffer = (w.HMODULE * slot_count)()
            needed = w.DWORD(0)
            if not w.EnumProcessModulesEx(
                handle,
                buffer,
                ctypes.sizeof(buffer),
                ctypes.byref(needed),
                filter_flag,
            ):
                break
            count = min(needed.value // ctypes.sizeof(w.HMODULE), slot_count)
            for index in range(count):
                module = buffer[index]
                if not module:
                    continue
                key = int(module or 0) & w.ADDRESS_MASK
                if key in seen_bases:
                    continue
                seen_bases.add(key)
                yield key, module
            if needed.value <= ctypes.sizeof(buffer):
                break
            slot_count *= 2


def _modules_from_regions(handle):
    """Derive the module manifest from the address space itself.

    Used when PSAPI cannot enumerate the modules of the target: the image
    regions name the same files, they just come in pieces.
    """
    seen_paths = set()
    groups = []
    index_of = {}
    for mbi in _walk_regions(handle):
        if mbi.State != w.MEM_COMMIT or mbi.Type != w.MEM_IMAGE:
            continue
        base = int(mbi.BaseAddress or 0) & w.ADDRESS_MASK
        size = int(mbi.RegionSize or 0) & w.ADDRESS_MASK
        allocation = int(mbi.AllocationBase or 0) & w.ADDRESS_MASK
        name = _mapped_device_name(handle, base)
        path = _usable_file_path(name) if name else None
        key = path if path is not None else ("base", allocation or base)
        if key in index_of:
            entry = groups[index_of[key]]
            entry["base"] = min(entry["base"], base)
            entry["size"] = max(entry["base"] + entry["size"], base + size) - entry["base"]
            continue
        if path is not None:
            if path in seen_paths:
                continue
            seen_paths.add(path)
        index_of[key] = len(groups)
        groups.append({"path": path, "base": base, "size": size})
    groups.sort(key=lambda item: item["base"])
    return groups


def modules(pid):
    """Return the loaded executable images, lowest base address first.

    Each image is listed once and each file path appears once, so an image
    mapped at several addresses does not fill the manifest with duplicates.
    An image whose path cannot be resolved to something openable is still
    listed, with ``path`` set to ``None``.
    """
    handle = _open_process(pid)
    try:
        entries = []
        seen_paths = set()
        for base, module in _enumerate_modules(handle):
            record = _module_record(handle, module, seen_paths)
            if record is not None:
                entries.append(record)
        if not entries:
            entries = _modules_from_regions(handle)
        entries.sort(key=lambda item: item["base"])
        return entries
    finally:
        _close_process(handle)

"""Virtual address space auditing for the wvas diagnostic collector.

The collector asks three questions about a target process:

``regions(pid)``
    Which parts of the virtual address space does the process have in use?

``file_backed_regions(pid)``
    Which of those parts are backed by a file on disk, and which file?

``modules(pid)``
    Which executable images are loaded, and where?

The answers are what the field engineers read when a machine reports
"something keeps the log file mapped" or "the process has no address space
left". They are held next to what a debugger shows and pasted into support
tickets, so every address has to be the one the system reports, at full
address width, and every path has to be one the caller can actually open.
"""

import bisect
import ctypes

from . import _winapi as w
from .errors import WVasError

# Characters in the scratch buffers used for names. 1 KiB comfortably covers
# \\?\Volume{...} style paths, long UNC names and the redirected device names
# a host shares into a virtual machine.
NAME_BUFFER_CHARS = 1024

# Device names that stand for a network share rather than a local volume.
_UNC_LIKE_DEVICES = (
    "\\device\\mup",
    "\\device\\lanmanredirector",
    "\\device\\webdavredirector",
    "\\device\\davwwwroot",
    "\\device\\tsclient",
)

_PROTECTION_NAMES = {
    w.PAGE_NOACCESS: "none",
    w.PAGE_READONLY: "r",
    w.PAGE_READWRITE: "rw",
    w.PAGE_WRITECOPY: "wc",
    w.PAGE_EXECUTE: "x",
    w.PAGE_EXECUTE_READ: "xr",
    w.PAGE_EXECUTE_READWRITE: "xrw",
    w.PAGE_EXECUTE_WRITECOPY: "xwc",
}

_TYPE_NAMES = {
    w.MEM_IMAGE: "image",
    w.MEM_MAPPED: "mapped",
    w.MEM_PRIVATE: "private",
}


def protection_name(protect):
    """Map a PAGE_* protection value onto its short textual name.

    A pure lookup: the modifier flags a region may carry (PAGE_GUARD,
    PAGE_NOCACHE, PAGE_WRITECOMBINE) are stripped and no process is queried.
    """
    return _PROTECTION_NAMES.get(protect & 0xFF, "?")


def type_name(region_type):
    """Map a MEM_* region type onto its short textual name.

    A pure lookup, no process is queried.
    """
    return _TYPE_NAMES.get(region_type, "private")


# ---------------------------------------------------------------------------
# turning a device name into a path the caller can open
# ---------------------------------------------------------------------------

def _is_openable(path):
    """True for a path the caller can hand to ``open()`` or to Explorer."""
    if not path:
        return False
    if path.startswith("\\\\"):
        # \\server\share is a UNC path; \\?\ and \\.\ are object manager
        # syntax that no shell and no file dialog understands.
        return not path.startswith("\\\\?\\") and not path.startswith("\\\\.\\")
    if path.startswith("\\"):
        return False
    return len(path) > 2 and path[1] == ":"


def _strip_volume_prefix(path):
    """Drop the volume prefixes CreateFile accepts but callers do not want."""
    if path.startswith("\\\\?\\UNC\\"):
        return "\\\\" + path[8:]
    if path.startswith("\\\\?\\") or path.startswith("\\\\.\\"):
        return path[4:]
    return path


def _dos_devices(drive):
    """The NT device names a drive letter stands for, longest first."""
    buffer = ctypes.create_unicode_buffer(NAME_BUFFER_CHARS)
    written = w.QueryDosDeviceW(drive, buffer, NAME_BUFFER_CHARS)
    if not written:
        return ()
    names = tuple(part for part in buffer.value.split("\0") if part)
    return tuple(sorted(names, key=len, reverse=True))


class _DeviceMap(object):
    """Lazily built map of NT device names onto openable DOS/UNC prefixes."""

    def __init__(self):
        self._map = None

    def _drives(self):
        buffer = ctypes.create_unicode_buffer(512)
        length = w.GetLogicalDriveStringsW(512, buffer)
        if not length:
            return ()
        return tuple(part for part in buffer.value.split("\0") if part)

    def _build(self):
        entries = {}
        for drive in self._drives():
            letter = drive.rstrip("\\")
            for device in _dos_devices(letter):
                entries.setdefault(device, letter)
        # A network drive reports \\server\share as its device name; keep it
        # reachable under the \??\UNC form the object manager uses too.
        for device, prefix in list(entries.items()):
            if device.startswith("\\\\"):
                entries.setdefault("\\??\\UNC" + device[1:], prefix)
        return entries

    def lookup(self, device):
        if self._map is None:
            self._map = self._build()
        return self._map.get(device)


_DEVICE_MAP = _DeviceMap()


def _translate_device_path(device_path):
    """Turn ``\\Device\\Volume\\dir\\file`` into a path the caller can open.

    Returns ``None`` when the name cannot be mapped back onto a DOS drive or
    a UNC share: a name nobody can open is not an answer a support ticket can
    use, so it is reported as "no usable file name" instead.
    """
    if not device_path:
        return None
    if _is_openable(device_path):
        return _strip_volume_prefix(device_path)

    if device_path.startswith("\\??\\UNC\\"):
        return "\\\\" + device_path[8:]
    if device_path.startswith("\\??\\"):
        return _translate_device_path(device_path[4:])
    if device_path.startswith("\\\\.\\GLOBALROOT\\"):
        return _translate_device_path(device_path[16:])

    index = device_path.find("\\", 1)
    if index <= 0:
        return None
    device = device_path[:index]
    rest = device_path[index:]

    if device.lower() in _UNC_LIKE_DEVICES or device.lower().startswith("\\device\\unc"):
        candidate = "\\\\" + rest.lstrip("\\")
        return candidate if _is_openable(candidate) else None

    prefix = _DEVICE_MAP.lookup(device)
    if prefix is None:
        prefix = _DEVICE_MAP.lookup(device.lower())
    if prefix is None:
        return None
    return prefix + rest


def _open_for_metadata(path):
    """Open ``path`` for metadata only, or return ``None``."""
    handle = w.CreateFileW(
        path,
        0,
        w.FILE_SHARE_READ | w.FILE_SHARE_WRITE | w.FILE_SHARE_DELETE,
        None,
        w.OPEN_EXISTING,
        w.FILE_FLAG_BACKUP_SEMANTICS,
        None,
    )
    if not handle or handle == w.INVALID_HANDLE_VALUE:
        return None
    return handle


def _final_dos_path(device_path):
    """Resolve an NT device name to a DOS path through the object manager.

    ``\\\\.\\GLOBALROOT\\<device path>`` lets the object manager walk the name
    and ``GetFinalPathNameByHandle`` reports where the file system really has
    it, which also covers volumes that carry no drive letter.
    """
    handle = _open_for_metadata("\\\\.\\GLOBALROOT" + device_path)
    if handle is None:
        return None
    try:
        buffer = ctypes.create_unicode_buffer(NAME_BUFFER_CHARS)
        written = w.GetFinalPathNameByHandleW(
            handle, buffer, NAME_BUFFER_CHARS, w.VOLUME_NAME_DOS
        )
        if written >= NAME_BUFFER_CHARS:
            bigger = ctypes.create_unicode_buffer(written + 1)
            written = w.GetFinalPathNameByHandleW(
                handle, bigger, written + 1, w.VOLUME_NAME_DOS
            )
            if not written:
                return None
            buffer = bigger
        if not written:
            return None
        path = _strip_volume_prefix(buffer.value)
        return path if _is_openable(path) else None
    finally:
        w.CloseHandle(handle)


def _usable_file_path(name):
    """The openable path behind a name the system reported, or ``None``."""
    if not name:
        return None
    path = _translate_device_path(name)
    if path is not None:
        return path
    if name.startswith("\\"):
        return _final_dos_path(name)
    return None


def _mapped_device_name(handle, address):
    """The raw name PSAPI reports for the file backing ``address``."""
    buffer = ctypes.create_unicode_buffer(NAME_BUFFER_CHARS)
    written = w.GetMappedFileNameW(
        handle, ctypes.c_void_p(address), buffer, NAME_BUFFER_CHARS
    )
    if not written:
        # Nothing is named here: an anonymous mapping, a decommitted view, or
        # a file that has since gone away. Callers read that as "no file".
        return None
    if written >= NAME_BUFFER_CHARS:
        bigger = ctypes.create_unicode_buffer(written + 1)
        if not w.GetMappedFileNameW(
            handle, ctypes.c_void_p(address), bigger, written + 1
        ):
            return None
        return bigger.value
    return buffer.value


def _module_device_name(handle, module, base):
    """The name of a loaded module, as openable as it can be made."""
    buffer = ctypes.create_unicode_buffer(NAME_BUFFER_CHARS)
    written = w.GetModuleFileNameExW(handle, module, buffer, NAME_BUFFER_CHARS)
    name = buffer.value if written else ""
    if not name:
        name = _mapped_device_name(handle, base) or ""
    return _usable_file_path(name)


# ---------------------------------------------------------------------------
# opening and classifying failures on the target
# ---------------------------------------------------------------------------

def _ensure_supported():
    if not w.is_windows():
        raise WVasError("wvas audits Windows address spaces only", kind="unsupported")


def _check_pid(pid):
    """Reject anything that cannot name a Windows process."""
    if isinstance(pid, bool) or not isinstance(pid, int):
        raise WVasError(
            "pid must be a non-negative integer, got %r" % (pid,),
            kind="badarg",
            pid=pid,
        )
    if pid <= 0 or pid > 0xFFFFFFFF:
        raise WVasError(
            "%r is not a valid process id" % (pid,), kind="badarg", pid=pid
        )


def _process_exists(pid):
    """True when ``pid`` names a process that is running right now."""
    handle = w.OpenProcess(w.PROCESS_QUERY_LIMITED_INFORMATION, False, pid)
    if handle:
        exited = _has_exited(handle)
        w.CloseHandle(handle)
        return not exited
    if w.last_error() != w.ERROR_ACCESS_DENIED:
        return False
    # Access denied is only ever reported for a process that does exist.
    snapshot = ctypes.create_string_buffer(4 * 4096)
    needed = w.DWORD(0)
    if not w.EnumProcesses(
        ctypes.cast(snapshot, w.PDWORD), ctypes.sizeof(snapshot), ctypes.byref(needed)
    ):
        return False
    found = ctypes.cast(snapshot, ctypes.POINTER(w.DWORD))
    return any(found[i] == pid for i in range(needed.value // 4))


def _has_exited(handle):
    """True when the process behind ``handle`` has already terminated."""
    code = w.DWORD(0)
    if not w.GetExitCodeProcess(handle, ctypes.byref(code)):
        return False
    return code.value != w.STILL_ACTIVE


def _fail_to_open(error, pid):
    """Raise the classified failure for an OpenProcess that did not work."""
    if error == w.ERROR_ACCESS_DENIED:
        kind = "access-denied"
    elif error == w.ERROR_INVALID_PARAMETER or not _process_exists(pid):
        kind = "no-such-process"
    else:
        kind = "query-failed"
    raise WVasError(
        "cannot open process %s (Win32 error %s)" % (pid, error), kind=kind, pid=pid
    )


def _open_process(pid):
    """Open ``pid`` so its address space can be inspected."""
    _ensure_supported()
    _check_pid(pid)
    handle = w.OpenProcess(
        w.PROCESS_QUERY_INFORMATION
        | w.PROCESS_QUERY_LIMITED_INFORMATION
        | w.PROCESS_VM_READ,
        False,
        pid,
    )
    if not handle and w.last_error() == w.ERROR_ACCESS_DENIED:
        # Reading mapped file names wants the full query right, but walking
        # the address space itself only needs the limited one.
        handle = w.OpenProcess(w.PROCESS_QUERY_LIMITED_INFORMATION, False, pid)
    if not handle:
        _fail_to_open(w.last_error(), pid)
    if _has_exited(handle):
        # The pid was valid a moment ago; the process is gone now.
        w.CloseHandle(handle)
        raise WVasError(
            "process %s has exited" % (pid,), kind="no-such-process", pid=pid
        )
    return handle


# ---------------------------------------------------------------------------
# the target process
# ---------------------------------------------------------------------------

class _Process(object):
    """A target process opened for reading, with its address space walkable.

    Addresses and sizes are read at the width the *target* reports with, so a
    64-bit address space and a region larger than 4 GiB both arrive intact
    whatever the width of this interpreter is.
    """

    def __init__(self, pid):
        self.pid = pid
        self.handle = _open_process(pid)
        self._struct = w.mbi_struct(self.handle)
        self._limit = min(
            (1 << 47) - 1 if self._struct is w.MEMORY_BASIC_INFORMATION64 else (1 << 32) - 1,
            w.ADDRESS_MASK,
        )
        self._modules = None
        self._image_starts = None

    def close(self):
        if self.handle:
            w.CloseHandle(self.handle)
            self.handle = None

    def __enter__(self):
        return self

    def __exit__(self, *exc_info):
        self.close()
        return False

    # -- address space ------------------------------------------------------

    def _query(self, address, mbi):
        """One VirtualQueryEx step.

        Returns the number of bytes written, or ``None`` when ``address`` lies
        past the end of the target's address space. Anything else is a query
        that genuinely failed and is reported as such.
        """
        written = w.VirtualQueryEx(
            self.handle, ctypes.c_void_p(address), ctypes.byref(mbi), ctypes.sizeof(mbi)
        )
        if written:
            return written
        error = w.last_error()
        if error in w.END_OF_SPACE_ERRORS:
            return None
        if error == w.ERROR_ACCESS_DENIED:
            raise WVasError(
                "not allowed to read the address space of process %s" % self.pid,
                kind="access-denied",
                pid=self.pid,
            )
        if error == w.ERROR_INVALID_HANDLE or not _process_exists(self.pid):
            raise WVasError(
                "process %s went away while it was being audited" % self.pid,
                kind="no-such-process",
                pid=self.pid,
            )
        raise WVasError(
            "VirtualQueryEx failed at 0x%x (Win32 error %s)" % (address, error),
            kind="query-failed",
            pid=self.pid,
        )

    def walk(self):
        """Yield the MEMORY_BASIC_INFORMATION of every region, low to high."""
        mbi = self._struct()
        address = 0
        while address <= self._limit:
            if self._query(address, mbi) is None:
                return
            base = int(mbi.BaseAddress or 0)
            size = int(mbi.RegionSize or 0)
            if mbi.State in (w.MEM_COMMIT, w.MEM_RESERVE):
                yield mbi
            if size == 0:
                return
            next_address = base + size
            if next_address <= address:
                return
            address = next_address

    # -- images -------------------------------------------------------------

    def _enumerate_modules(self):
        """Yield the base address of every module PSAPI can see."""
        seen = set()
        for filter_flag in (
            w.LIST_MODULES_ALL,
            w.LIST_MODULES_DEFAULT,
            w.LIST_MODULES_32BIT,
            w.LIST_MODULES_64BIT,
        ):
            slot_count = 1024
            for _attempt in range(6):
                buffer = (w.HMODULE * slot_count)()
                needed = w.DWORD(0)
                if not w.EnumProcessModulesEx(
                    self.handle,
                    buffer,
                    ctypes.sizeof(buffer),
                    ctypes.byref(needed),
                    filter_flag,
                ):
                    break
                count = min(needed.value // ctypes.sizeof(w.HMODULE), slot_count)
                for index in range(count):
                    module = buffer[index]
                    if not module:
                        continue
                    base = int(module or 0) & w.ADDRESS_MASK
                    if base in seen:
                        continue
                    seen.add(base)
                    yield base, module
                if needed.value <= ctypes.sizeof(buffer):
                    break
                slot_count *= 2

    def module_records(self):
        """The loaded images: ``(base, size, path)`` sorted by base address.

        Each file is reported once, so an image that is mapped at several
        addresses does not fill the manifest with duplicates. An image whose
        name cannot be made into a path the caller can open is still listed,
        with ``None`` for its path.
        """
        if self._modules is not None:
            return self._modules
        records = []
        seen_paths = set()
        for base, module in self._enumerate_modules():
            size = 0
            info = w.MODULEINFO()
            if w.GetModuleInformation(
                self.handle, module, ctypes.byref(info), ctypes.sizeof(info)
            ):
                base = int(info.lpBaseOfDll or 0) & w.ADDRESS_MASK or base
                size = int(info.SizeOfImage or 0)
            if not base:
                continue
            path = _module_device_name(self.handle, module, base)
            if path is not None:
                if path in seen_paths:
                    continue
                seen_paths.add(path)
            records.append((base, size, path))
        records.sort(key=lambda item: item[0])
        self._modules = records
        return records

    def image_path_at(self, address):
        """The image a region belongs to, when the module list names it."""
        if self._image_starts is None:
            self._image_starts = [item[0] for item in self.module_records()]
        index = bisect.bisect_right(self._image_starts, address) - 1
        if index < 0:
            return None
        base, size, path = self.module_records()[index]
        if path is None:
            return None
        if size and address >= base + size:
            return None
        return path

    # -- descriptors --------------------------------------------------------

    def region_path(self, mbi, base, region_type, state):
        """The openable path of the file behind a region, or ``None``."""
        if state != w.MEM_COMMIT or region_type not in (w.MEM_IMAGE, w.MEM_MAPPED):
            return None
        name = _mapped_device_name(self.handle, base)
        path = _usable_file_path(name) if name else None
        if path is None and region_type == w.MEM_IMAGE:
            # The kernel names some images with a device path that has no DOS
            # equivalent (a host directory shared into a virtual machine, say)
            # while the module list knows where the file really is.
            path = self.image_path_at(base)
        return path

    def describe(self, mbi):
        """Build one region descriptor from a filled-in MEMORY_BASIC_INFORMATION."""
        base = int(mbi.BaseAddress or 0) & w.ADDRESS_MASK
        size = int(mbi.RegionSize or 0) & w.ADDRESS_MASK
        region_type = int(mbi.Type or 0)
        state = int(mbi.State or 0)
        protect = int(mbi.Protect or 0)
        if protect == 0:
            # Reserved memory carries no protection of its own; report the one
            # the allocation as a whole was reserved with.
            protect = int(mbi.AllocationProtect or 0)
        return {
            "base": base,
            "size": size,
            "state": "commit" if state == w.MEM_COMMIT else "reserve",
            "type": type_name(region_type),
            "protect": protection_name(protect),
            "path": self.region_path(mbi, base, region_type, state),
            "image": region_type == w.MEM_IMAGE,
        }

    def regions(self, include_reserved):
        result = []
        for mbi in self.walk():
            if not include_reserved and mbi.State != w.MEM_COMMIT:
                continue
            result.append(self.describe(mbi))
        result.sort(key=lambda item: (item["base"], item["size"]))
        return result


# ---------------------------------------------------------------------------
# public API
# ---------------------------------------------------------------------------

def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    Every committed region is reported, and every reserved one too unless
    ``include_reserved`` is false. Addresses and sizes come back at full
    width and the list is ascending by ``base``.
    """
    with _Process(pid) as target:
        return target.regions(include_reserved)


def file_backed_regions(pid):
    """Return only the regions that have a file behind them."""
    return [item for item in regions(pid) if item["path"] is not None]


def modules(pid):
    """Return the loaded executable images, lowest base address first.

    Each image is listed once and each file path appears once. An image whose
    path cannot be resolved into something the caller can open is still
    listed, with ``path`` set to ``None``.
    """
    with _Process(pid) as target:
        return [
            {"path": path, "base": base, "size": size}
            for base, size, path in target.module_records()
        ]
